∀ (x : Bool × List (Fin 10)),
  NativeBridge.Incremental.NumberRepresentation.DecimalPart.signedOf x =
    if x.fst = true then Rocq.Corelib.Init.Decimal.signed_int.Neg (NativeBridge.decimalDigitsOf x.snd)
    else Rocq.Corelib.Init.Decimal.signed_int.Pos (NativeBridge.decimalDigitsOf x.snd)

∀ (x : Bool × List (Fin 16)),
  NativeBridge.Incremental.NumberRepresentation.HexadecimalPart.signedOf x =
    if x.fst = true then Rocq.Corelib.Init.Hexadecimal.signed_int.Neg (NativeBridge.hexadecimalDigitsOf x.snd)
    else Rocq.Corelib.Init.Hexadecimal.signed_int.Pos (NativeBridge.hexadecimalDigitsOf x.snd)
